// static/app.css is generated by `make css` from styles.css; it is embedded when present.
//
//go:embed static templates
var files embed.FS

const sessionCookie = "hausbuch_session"

type server struct {
	users      *user.Store
	pages      *page.Store
	stock      *stock.Store
	version    string
	templates  map[string]*template.Template
	editors    *editors
	passkeys   *webauthn.WebAuthn // nil when passkeys can't be offered
	ceremonies *ceremonies
	proxies    []netip.Prefix // whose X-Forwarded-For is believed
	limits     *limiter
}

// view is what every template gets: the signed-in user, if any, the text searched for, shown in the header's search
// field, the running version, and the page's own data.
type view struct {
	User    *user.User
	Search  string
	Version string
	Data    any
}

// repository is where releases are published and problems reported.
const repository = "https://github.com/davidepedone/hausbuch"

// choiceField is what the choiceField part shows: a text field with its suggestions, List naming their datalist.
type choiceField struct {
	Name, Label string
	Optional    bool
	Value, List string
	Choices     []string
}

func field(name, label string, optional bool, value, list string, choices []string) choiceField {
	return choiceField{Name: name, Label: label, Optional: optional, Value: value, List: list, Choices: choices}
}

// releaseURL is the page of the version's release notes, or the list of releases for a build that isn't a release.
func releaseURL(version string) string {
	if version == "dev" {
		return repository + "/releases"
	}
	return repository + "/releases/tag/v" + version
}

var funcs = template.FuncMap{
	"date":       func(t time.Time) string { return t.Local().Format("2 Jan 2006, 15:04") },
	"names":      joinNames,
	"day":        func(t time.Time) string { return t.Local().Format("2 Jan 2006") },
	"newPageURL": newPageURL,
	"pageURL":    pageURL,
	"types":      func() []page.Type { return page.Types },
	"sections":   func() []stock.Section { return stock.Sections },
	// calendar shows a date that has no time of day, such as an expiry date, which must not move with the time zone.
	"calendar":    func(t time.Time) string { return t.Format("2 Jan 2006") },
	"inputDate":   inputDate,
	"itemForm":    formOf,
	"itemURL":     itemURL,
	"locationURL": locationURL,
	"field":       field,
	"expiryNote":  expiryNote,
	"expired":     func(s stock.State) bool { return s == stock.Expired },
	"expiring":    func(s stock.State) bool { return s == stock.Expiring },
	// lower is a category's key, as the list filter's chips name it.
	"lower":       strings.ToLower,
	"shopKey":     stock.ShopKey,
	"releaseURL":  releaseURL,
	"reportURL":   func() string { return repository + "/issues/new/choose" },
	"linkMinutes": func() int { return int(user.LinkLifetime.Minutes()) },
	"minPassword": func() int { return user.MinPasswordLength },
	"maxPassword": func() int { return user.MaxPasswordLength },
	"passkeyID":   func(id []byte) string { return base64.RawURLEncoding.EncodeToString(id) },
}

// NewHandler returns the application's HTTP handler. Everything except signing in, sign-in links, static assets and
// the health check requires a session; version is the running release, or "dev". proxies are the trusted proxies, from
// ParseTrustedProxies.
func NewHandler(users *user.Store, pages *page.Store, items *stock.Store, version string, passkeys *webauthn.WebAuthn,
	proxies []netip.Prefix) http.Handler {
	s := &server{users: users, pages: pages, stock: items, version: version, passkeys: passkeys, proxies: proxies,
		templates: map[string]*template.Template{}, limits: &limiter{},
		editors: &editors{open: map[editorKey]*editor{}}, ceremonies: &ceremonies{m: map[string]ceremony{}}}
	for _, name := range []string{"home", "login", "password", "page", "edit", "editing", "deleted", "history",
		"revision", "compare", "search", "section", "item", "move", "shopping", "putaway", "pantry", "locations", "location", "link", "offer"} {
		s.templates[name] = template.Must(template.New(name).Funcs(funcs).
			ParseFS(files, "templates/layout.html", "templates/parts.html", "templates/"+name+".html"))
	}
	static, err := fs.Sub(files, "static")
	if err != nil {
		panic(err)
	}

	signedIn := http.NewServeMux()
	signedIn.HandleFunc("GET /{$}", s.home)
	signedIn.HandleFunc("GET /pages/new", s.newPage)
	signedIn.HandleFunc("POST /pages", s.createPage)
	signedIn.HandleFunc("GET /pages/{id}", s.viewPage)
	signedIn.HandleFunc("GET /pages/{id}/edit", s.editPage)
	signedIn.HandleFunc("POST /pages/{id}", s.savePage)
	signedIn.HandleFunc("POST /pages/{id}/delete", s.deletePage)
	signedIn.HandleFunc("POST /pages/{id}/restore", s.restorePage)
	signedIn.HandleFunc("GET /pages/{id}/pantry", s.pantryCheck)
	signedIn.HandleFunc("POST /pages/{id}/pantry", s.addIngredients)
	signedIn.HandleFunc("GET /locations", s.locations)
	signedIn.HandleFunc("GET /locations/{name}", s.location)
	signedIn.HandleFunc("GET /deleted", s.deletedPages)
	signedIn.HandleFunc("GET /search", s.search)
	signedIn.HandleFunc("POST /preview", s.preview)
	signedIn.HandleFunc("POST /pages/skeleton", s.skeleton)
	signedIn.HandleFunc("POST /pages/{id}/editing", s.stillEditing)
	signedIn.HandleFunc("POST /pages/{id}/cancel", s.cancelEdit)
	signedIn.HandleFunc("GET /pages/{id}/history", s.history)
	signedIn.HandleFunc("GET /pages/{id}/revisions/{n}", s.revision)
	signedIn.HandleFunc("GET /pages/{id}/revisions/{n}/compare", s.compare)
	signedIn.HandleFunc("POST /pages/{id}/revisions/{n}/restore", s.restoreRevision)
	s.routeStock(signedIn)
	s.routeShopping(signedIn)
	signedIn.HandleFunc("POST /logout", s.logout)
	signedIn.HandleFunc("GET /account/password", func(w http.ResponseWriter, r *http.Request) {
		s.renderAccount(w, r, http.StatusOK, passwordData{})
	})
	signedIn.HandleFunc("POST /account/password", s.changePassword)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte("ok"))
	})
	mux.Handle("GET /static/", http.StripPrefix("/static/", http.FileServerFS(static)))
	mux.HandleFunc("GET /login", s.limited(s.loginPage))
	mux.HandleFunc("POST /login", s.limited(s.login))
	mux.HandleFunc("GET /link/{token}", s.limited(s.linkPage))
	mux.HandleFunc("POST /link/{token}", s.limited(s.useLink))
	s.routePasskeys(mux, signedIn)
	mux.Handle("/", s.requireSession(signedIn))

	return http.NewCrossOriginProtection().Handler(mux)
}

type ctxKey struct{}

func currentUser(r *http.Request) *user.User {
	u, _ := r.Context().Value(ctxKey{}).(*user.User)
	return u
}

// requireSession lets through requests with a valid session, refreshing its cookie, and turns away the others
// before they reach routing, so that nothing is revealed about what exists.
func (s *server) requireSession(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var sess user.Session
		c, err := r.Cookie(sessionCookie)
		if err == nil {
			sess, err = s.users.LookupSession(r.Context(), c.Value)
		}
		if err != nil {
			if !errors.Is(err, http.ErrNoCookie) && !errors.Is(err, user.ErrNoSession) {
				slog.Error("look up session", "err", err)
			}
			if r.Method == http.MethodGet {
				http.Redirect(w, r, "/login?next="+url.QueryEscape(r.URL.RequestURI()), http.StatusSeeOther)
			} else {
				http.Error(w, "Sign in first.", http.StatusUnauthorized)
			}
			return
		}
		setSessionCookie(w, r, sess)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, &sess.User)))
	})
}

func setSessionCookie(w http.ResponseWriter, r *http.Request, sess user.Session) {
	http.SetCookie(w, &http.Cookie{
		Name:     sessionCookie,
		Value:    sess.Token,
		Path:     "/",
		Expires:  sess.Expires,
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
		Secure:   isHTTPS(r),
	})
}

// isHTTPS reports whether the browser reached us over HTTPS, directly or through a proxy terminating it. A forged
// header can only make the cookie Secure, which breaks the forger's own session over plain HTTP.
func isHTTPS(r *http.Request) bool {
	return r.TLS != nil || r.Header.Get("X-Forwarded-Proto") == "https"
}

type loginData struct {
	NoAccounts bool
	Error      string
	Username   string
	Next       string
	Passkeys   bool // whether passkey sign-in is offered
}

func (s *server) loginPage(w http.ResponseWriter, r *http.Request) {
	s.renderLogin(w, r, http.StatusOK, loginData{Next: r.URL.Query().Get("next")})
}

func (s *server) renderLogin(w http.ResponseWriter, r *http.Request, status int, data loginData) {
	users, err := s.users.List(r.Context())
	if err != nil {
		s.fail(w, err)
		return
	}
	data.NoAccounts, data.Passkeys = len(users) == 0, s.passkeys != nil
	s.render(w, r, status, "login", data)
}

func (s *server) login(w http.ResponseWriter, r *http.Request) {
	username, password, next := r.PostFormValue("username"), r.PostFormValue("password"), r.PostFormValue("next")
	u, err := s.users.Authenticate(r.Context(), username, password, s.address(r))
	switch {
	case errors.Is(err, user.ErrBadCredentials):
		s.renderLogin(w, r, http.StatusUnauthorized,
			loginData{Error: "Invalid username or password.", Username: username, Next: next})
		return
	case errors.Is(err, user.ErrBusy):
		s.logEvent(r, slog.LevelWarn, "password checks busy", "unknown")
		s.renderLogin(w, r, http.StatusServiceUnavailable, loginData{Error: busy, Username: username, Next: next})
		return
	}
	if err != nil {
		s.fail(w, err)
		return
	}
	s.signIn(w, r, u, next)
}

// signIn starts a session for u and sends them on to next, if it is a path on this site, by way of the passkey offer
// when passkeys are on and u has none.
func (s *server) signIn(w http.ResponseWriter, r *http.Request, u user.User, next string) {
	sess, err := s.users.CreateSession(r.Context(), u)
	if err != nil {
		s.fail(w, err)
		return
	}
	setSessionCookie(w, r, sess)
	next = localPath(next)
	if s.passkeys != nil {
		keys, err := s.users.Passkeys(r.Context(), u.ID)
		if err != nil {
			s.fail(w, err)
			return
		}
		if len(keys) == 0 {
			next = "/account/passkeys/offer?next=" + url.QueryEscape(next)
		}
	}
	http.Redirect(w, r, next, http.StatusSeeOther)
}

// localPath returns next if it is a path on this site, and "/" otherwise, so that the login form can't be used to
// send someone to another site.
func localPath(next string) string {
	u, err := url.Parse(next)
	if err != nil || u.Scheme != "" || u.Host != "" || !strings.HasPrefix(next, "/") ||
		strings.HasPrefix(next, "//") || strings.HasPrefix(next, `/\`) {
		return "/"
	}
	return next
}

func (s *server) logout(w http.ResponseWriter, r *http.Request) {
	if c, err := r.Cookie(sessionCookie); err == nil {
		if err := s.users.DeleteSession(r.Context(), c.Value); err != nil {
			s.fail(w, err)
			return
		}
	}
	http.SetCookie(w, &http.Cookie{Name: sessionCookie, Path: "/", MaxAge: -1, Expires: time.Unix(0, 0)})
	http.Redirect(w, r, "/login", http.StatusSeeOther)
}

// busy is what a sign-in or password change is told when it waited too long for its password check.
const busy = "Too many sign-ins at once. Try again in a moment."

// refusals say why a new password was refused.
var refusals = map[error]string{
	user.ErrPasswordTooShort: fmt.Sprintf("The new password must be at least %d characters.", user.MinPasswordLength),
	user.ErrPasswordTooLong:  fmt.Sprintf("The new password can be at most %d characters.", user.MaxPasswordLength),
	user.ErrPasswordCommon:   "The new password is too common. Choose another.",
	user.ErrPasswordPersonal: "The new password must differ from your username and display name.",
}

type passwordData struct {
	Error   string
	Changed bool
	// Passkeys are the user's, listed when PasskeysOn.
	PasskeysOn bool
	Passkeys   []user.Passkey
}

// renderAccount shows the account page, with the user's passkeys when passkeys are on.
func (s *server) renderAccount(w http.ResponseWriter, r *http.Request, status int, d passwordData) {
	if d.PasskeysOn = s.passkeys != nil; d.PasskeysOn {
		var err error
		if d.Passkeys, err = s.users.Passkeys(r.Context(), currentUser(r).ID); err != nil {
			s.fail(w, err)
			return
		}
	}
	s.render(w, r, status, "password", d)
}

func (s *server) changePassword(w http.ResponseWriter, r *http.Request) {
	current, password, repeat := r.PostFormValue("current"), r.PostFormValue("new"), r.PostFormValue("repeat")
	if password != repeat {
		s.renderAccount(w, r, http.StatusBadRequest, passwordData{Error: "The two new passwords don't match."})
		return
	}
	err := s.users.ChangePassword(r.Context(), currentUser(r).ID, current, password)
	switch {
	case errors.Is(err, user.ErrBadCredentials):
		s.renderAccount(w, r, http.StatusBadRequest, passwordData{Error: "The current password is wrong."})
	case errors.Is(err, user.ErrBusy):
		s.logEvent(r, slog.LevelWarn, "password checks busy", currentUser(r).Username)
		s.renderAccount(w, r, http.StatusServiceUnavailable, passwordData{Error: busy})
	case refusals[err] != "":
		s.renderAccount(w, r, http.StatusBadRequest, passwordData{Error: refusals[err]})
	case err != nil:
		s.fail(w, err)
	default:
		s.logEvent(r, slog.LevelInfo, "password changed", currentUser(r).Username)
		s.renderAccount(w, r, http.StatusOK, passwordData{Changed: true})
	}
}

// render executes a page into a buffer first, so that a template error becomes a clean 500 rather than half a page.
func (s *server) render(w http.ResponseWriter, r *http.Request, status int, name string, data any) {
	var buf bytes.Buffer
	v := view{User: currentUser(r), Version: s.version, Data: data}
	if r.URL.Path == "/search" {
		v.Search = r.URL.Query().Get("q")
	}
	if err := s.templates[name].ExecuteTemplate(&buf, "layout", v); err != nil {
		s.fail(w, err)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(status)
	_, _ = buf.WriteTo(w)
}

// renderPart answers an HTMX request with one part, a template defined in the page's file, of a page.
func (s *server) renderPart(w http.ResponseWriter, name, part string, data any) {
	var buf bytes.Buffer
	if err := s.templates[name].ExecuteTemplate(&buf, part, data); err != nil {
		s.fail(w, err)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = buf.WriteTo(w)
}

// logEvent writes a security event to the log, with the account it concerns, "unknown" when there is none, and the
// client's address. It never gets passwords or tokens.
func (s *server) logEvent(r *http.Request, level slog.Level, msg, username string, args ...any) {
	slog.Log(r.Context(), level, msg, append([]any{"user", username, "address", s.address(r)}, args...)...)
}

func (s *server) fail(w http.ResponseWriter, err error) {
	slog.Error("request failed", "err", err)
	http.Error(w, "Something went wrong.", http.StatusInternalServerError)
}
